def delta_fd(price, S, h=0.01):
    """Slope of price at S, from prices at S + h and S - h."""
    return (price(S + h) - price(S - h)) / (2 * h)

def hedge_shares(n_short, delta):
    """Whole shares to buy against n_short sold options."""
    return round(n_short * delta)

